import { h, Host, Prop, State, Component, type ComponentInterface } from '@stencil/core';

const PREFIX = 'pager__jumper';

@Component({
  tag: 'ks-pagination-quick-jumper',
  styleUrl: 'ks-pagination.scss',
  shadow: true,
})
export class PaginationQuickJumper implements ComponentInterface {
  // const { disabled = false, onJump, totalPageCount } = props;
  @Prop() disabled = false;

  @Prop() onJump?: (page: number) => void;

  @Prop() totalPageCount?: number;

  @State() value = '';

  private page: number | undefined;

  private handleJumpPage = () => {
    if (this.disabled || this.page === undefined) return;
    this.value = this.page.toString();
    this.onJump?.(this.page);
  };

  private handleKeyPress = (event: KeyboardEvent) => {
    if (event.key === 'Enter') {
      this.handleJumpPage();
    }
  };

  private handleChange = ({ detail }: CustomEvent<string>) => {
    const validPage = Math.min(Number(detail), this.totalPageCount || Number.MAX_SAFE_INTEGER);
    this.value = detail;
    if (isNaN(validPage)) return;
    this.page = validPage;
  };

  render() {
    return (
      <Host>
        <ks-space compact class={PREFIX} part="quickJumper">
          <ks-input
            class={`${PREFIX}-input`}
            size="sm"
            type="number"
            placeholder="#"
            disabled={this.disabled}
            value={this.value}
            onKsChange={this.handleChange}
            onKeyPress={this.handleKeyPress}
            data-testid="ks-pagination-index-iuKszv"
          />
          <ks-button
            class={`${PREFIX}-button`}
            size="sm"
            variant="inverse"
            disabled={this.disabled}
            onClick={this.handleJumpPage}
            data-testid="ks-pagination-index-sdz5ZP"
          >
            <slot />
          </ks-button>
        </ks-space>
      </Host>
    );
  }
}
